param(
    [Parameter(Mandatory=$true)][string]$Src,
    [Parameter(Mandatory=$true)][string]$Dst
)

$ErrorActionPreference = "Stop"
$mutex = New-Object System.Threading.Mutex($false, "Local\VelaGuard.PresentationRender")
$hasLock = $false
try {
    $hasLock = $mutex.WaitOne(180000)
    if (-not $hasLock) { throw "render mutex timeout" }

    $ppt = New-Object -ComObject PowerPoint.Application
    $pres = $ppt.Presentations.Open($Src, $false, $false, $false)
    try {
        # 24 = ppSaveAsOpenXMLPresentation, -1 = msoTrue
        $pres.SaveAs($Dst, 24, -1)
        Write-Output ("saved {0}" -f $Dst)
    }
    finally {
        if ($pres -ne $null) { $pres.Close() }
        [System.Runtime.InteropServices.Marshal]::ReleaseComObject($pres) | Out-Null
        [System.Runtime.InteropServices.Marshal]::ReleaseComObject($ppt) | Out-Null
    }
}
finally {
    if ($hasLock) { $mutex.ReleaseMutex() }
    $mutex.Dispose()
}

param(
    [string]$Pptx = "",
    [string]$OutDir = "validation\pptx-preview"
)

$ErrorActionPreference = "Stop"
$root = Split-Path -Parent $MyInvocation.MyCommand.Path
if ([string]::IsNullOrWhiteSpace($Pptx)) {
    $Pptx = (Get-ChildItem (Join-Path $root "exports\*.pptx") |
             Sort-Object LastWriteTime | Select-Object -Last 1).FullName
}
$src = $Pptx
$out = Join-Path $root $OutDir
if (-not (Test-Path $out)) { New-Item -ItemType Directory -Path $out | Out-Null }
Get-ChildItem $out -Filter *.png | Remove-Item -Force

$ppt = $null
$pres = $null
try {
    $ppt = New-Object -ComObject PowerPoint.Application
    $pres = $ppt.Presentations.Open($src, $true, $false, $false)
    for ($i = 1; $i -le $pres.Slides.Count; $i++) {
        $file = Join-Path $out ("slide_{0:d2}.png" -f $i)
        $pres.Slides.Item($i).Export($file, "PNG", 2560, 1440)
    }
    Write-Output ("exported {0} slides -> {1}" -f $pres.Slides.Count, $out)
}
finally {
    if ($pres -ne $null) { $pres.Close() }
    if ($ppt -ne $null) { $ppt.Quit() }
    [System.Runtime.InteropServices.Marshal]::ReleaseComObject($ppt) | Out-Null
}

